/// <summary>
/// NS Zelinka 29.02.24
/// </summary>
/// <param name="sender">FormDataSource</param>
/// <param name="e">Not used</param>
[FormDataSourceEventHandler(    formDataSourceStr(  AVAPTMToolTable, PTMToolTable), 
                                                    FormDataSourceEventType::Activated  ),
                                SuppressBPWarning(  'BPParameterNotUsed', 
                                                    'False positive'        )               ]
public static void PTMToolTable_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
{
    KCS_PTMToolTable    kcs_PTMToolTable;
    FormRun             formRun;
    WrkCtrTable         wrkCtrTable;

    boolean             locProjProductionExist;
    boolean             locProjMaintenanceExist;

    kcs_PTMToolTable        = sender.cursor();
    formRun                 = sender.formRun();
    wrkCtrTable             = wrkCtrTable::find(kcs_PTMToolTable.ToolId);

    if(kcs_PTMToolTable.RecId)
    {
        locProjProductionExist  = kcs_PTMToolTable.avaICProjProductionExist();
        locProjMaintenanceExist = kcs_PTMToolTable.avaICProjMaintenanceExist();
    }

    /*
    formRun.design().controlName(formControlStr(AVAPTMToolTable, AVAProjectCreationPP)).enabled(!kcs_PTMToolTable.AVAICProjProd);
    formRun.design().controlName(formControlStr(AVAPTMToolTable, AVAProjectCreationSP)).enabled(!kcs_PTMToolTable.AVAICProjMaintenance);
    formRun.design().controlName(formControlStr(AVAPTMToolTable, AVAProductionProject)).enabled(kcs_PTMToolTable.AVAICProjProd != '');
    formRun.design().controlName(formControlStr(AVAPTMToolTable, AVAServiceProject)).enabled(kcs_PTMToolTable.AVAICProjMaintenance != '');
    */
    formRun.design().controlName(formControlStr(AVAPTMToolTable, AVAProjectCreationPP)).enabled(!locProjProductionExist);
    formRun.design().controlName(formControlStr(AVAPTMToolTable, AVAProjectCreationSP)).enabled(!locProjMaintenanceExist);
    formRun.design().controlName(formControlStr(AVAPTMToolTable, AVAProductionProject)).enabled(locProjProductionExist);
    formRun.design().controlName(formControlStr(AVAPTMToolTable, AVAServiceProject)).enabled(locProjMaintenanceExist);

    formRun.design().controlName(formControlStr(AVAPTMToolTable, AVAWrkCtrDateCalendar)).enabled(wrkCtrTable.RecId);
}

/// <summary>
/// NS Zelinka 19.03.24
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(AVAPTMToolTable, AVAICProjProd_AVAICProjProd), FormControlEventType::Lookup)]
public static void AVAICProjProd_AVAICProjProd_OnLookup(FormControl sender, FormControlEventArgs e)
{
    KCS_PTMToolTable toolTable = sender.formRun().dataSource(formDataSourceStr(AVAPTMToolTable, PTMToolTable)).cursor();

    if (toolTable.KCS_ProducerUK == '' ||
        toolTable.KCS_ProducerUK == curExt())
    {
        AVAPTMToolTableFrm_Eventhandler::lookUpToProjTable(sender,e);
    }
    else
    {
        changecompany(toolTable.KCS_ProducerUK)
        {
            AVAPTMToolTableFrm_Eventhandler::lookUpToProjTable(sender,e);
        }
    }
}

