[FormControlEventHandler(formControlStr(AVAPTMToolTable, AVAICProjMaintenance_AVAICProjMaintenance), FormControlEventType::Lookup)]
public static void AVAICProjMaintenance_AVAICProjMaintenance_OnLookup(FormControl sender, FormControlEventArgs e)
{
    KCS_PTMToolTable toolTable = sender.formRun().dataSource(formDataSourceStr(AVAPTMToolTable, PTMToolTable)).cursor();

    if (toolTable.KCS_MaintenanceUK == '' ||
        toolTable.KCS_MaintenanceUK == curExt())
    {
