    }
}

/// <summary>
/// NS Zelinka 19.03.24
/// </summary>
/// <param name = "sender">FormControl</param>
/// <param name = "e">FormControlEventArgs</param>
public static void lookUpToProjTable(   FormControl             sender,
                                        FormControlEventArgs    e)
{
    SysTableLookup          sysTableLookup          = SysTableLookup::newParameters(tableNum(ProjTable), sender);
    Query                   query                   = new Query();
    QueryBuildDataSource    queryBuildDataSource;

    queryBuildDataSource    = query.addDataSource(tableNum(ProjTable));

    sysTableLookup.addLookupfield(fieldNum(ProjTable, ProjId));
    sysTableLookup.addLookupfield(fieldNum(ProjTable, Name));
    sysTableLookup.addLookupfield(fieldNum(ProjTable, Type));
    sysTableLookup.addLookupfield(fieldNum(ProjTable, CustAccount));

    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();

    FormControlCancelableSuperEventArgs cancelableSuperEventArgs = e as FormControlCancelableSuperEventArgs;
    cancelableSuperEventArgs.CancelSuperCall();
}

/// <summary>
/// AVA/WEN/2024/10/08    AVA_011503_CreateProject
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[    SuppressBPWarning('BPParameterNotUsed', 'False positive'),
    FormControlEventHandler(formControlStr(AVAPTMToolTable, AVAProductionProject), FormControlEventType::Clicked)]
public static void AVAProductionProject_OnClicked(FormControl sender, FormControlEventArgs e)
{
    KCS_PTMToolTable toolTable = sender.formRun().dataSource(formDataSourceStr(AVAPTMToolTable, PTMToolTable)).cursor();
    if (toolTable.KCS_ProducerUK != curExt())
    {
        appl.setDefaultCompany(toolTable.KCS_ProducerUK);
        SysSecurity::reload(false);
        SysDataAreaSelectExtension::fireDataAreaChanged();
    }
}

